{"intent":"find clear non-software outliers inside huong-dan phan-mem-cong-cu","expect":"candidate href list and reason tags for phase9 safe reclassification","script":"python3 - <<'PY'
import json,re,unicodedata
arts=json.load(open('data/articles.json',encoding='utf-8'))
rows=[a for a in arts if a.get('section')=='thu-vien' and a.get('libraryKindKey')=='huong-dan' and a.get('topicLv1Key')=='phan-mem-cong-cu']

def fold(s):
    s=(s or '').lower().replace('đ','d')
    s=''.join(c for c in unicodedata.normalize('NFD',s) if unicodedata.category(c)!='Mn')
    return re.sub(r'\s+',' ',s)

def has_sw_hint(t):
    t=fold(t)
    keys=['htkk','etax','thuế điện tử','misa','excel','word','vlookup','sumif','subtotal','fast','phan mem','phần mềm','tren misa','trên misa','tren excel','trên excel']
    return any(k in t for k in keys)

patterns=[
 ('labor-report',r'bao cao tinh hinh su dung lao dong'),
 ('tax-penalty',r'muc phat|xu phat|cham nop'),
 ('tax-deadline',r'lich nop|thoi han nop|gia han nop'),
 ('mst-or-tax-registration',r'ma so thue'),
 ('mon-bai',r'mon bai'),
 ('tax-return-general',r'to khai|quyet toan|ke khai'),
 ('invoice-general',r'hoa don'),
]
for tag,pat in patterns:
    rg=re.compile(pat,re.I)
    hits=[]
    for a in rows:
        t=fold(a['title'])
        if rg.search(t) and not has_sw_hint(a['title']):
            hits.append(a)
    print('\n##',tag,'count',len(hits))
    for a in hits[:120]:
        print(a.get('topicLv2Key'),a.get('topicLv3Key'),'|',a['title'],'|',a['href'])

print('\nALL WITHOUT SOFTWARE HINT')
for a in rows:
    if not has_sw_hint(a['title']):
        print(a['topicLv2Key'],a['topicLv3Key'],'|',a['title'],'|',a['href'])
PY","workdir":"/mnt/d/WORKING/KetoanThienUng/Ketoandieutam.com","timeout":120}
